function predictTheWinner(nums) {
  const n = nums.length;
  const memo = Array.from({ length: n }, () => new Array(n).fill(null));
  const lead = (l, r) => {
    if (l === r) return nums[l];
    if (memo[l][r] !== null) return memo[l][r];  // this range was solved before
    memo[l][r] = Math.max(nums[l] - lead(l + 1, r), nums[r] - lead(l, r - 1));
    return memo[l][r];
  };
  return lead(0, n - 1) >= 0;
}

from functools import cache

def predict_the_winner(nums):
    @cache                                # each range (l, r) is solved once
    def lead(l, r):
        if l == r:
            return nums[l]
        return max(nums[l] - lead(l + 1, r), nums[r] - lead(l, r - 1))
    return lead(0, len(nums) - 1) >= 0

