int lead(int[] nums, int l, int r) {
    if (l == r) return nums[l];
    if (memo[l][r] != null) return memo[l][r];   // this range was solved before
    memo[l][r] = Math.max(nums[l] - lead(nums, l + 1, r), nums[r] - lead(nums, l, r - 1));
    return memo[l][r];
}

int lead(vector<int>& nums, vector<vector<int>>& memo, vector<vector<bool>>& done, int l, int r) {
    if (l == r) return nums[l];
    if (done[l][r]) return memo[l][r];           // this range was solved before
    done[l][r] = true;
    return memo[l][r] = max(nums[l] - lead(nums, memo, done, l + 1, r), nums[r] - lead(nums, memo, done, l, r - 1));
}

bool predictTheWinner(vector<int>& nums) {
    int n = nums.size();
    vector<vector<int>> memo(n, vector<int>(n));
    vector<vector<bool>> done(n, vector<bool>(n));
    return lead(nums, memo, done, 0, n - 1) >= 0;
}
